-- GUIMMIA V76.6 - profiles, gates, legal map, workflows
on conflict(code) do update set family=excluded.family,label=excluded.label,workflow_slug=excluded.workflow_slug,active=true,updated_at=now();

on conflict(code) do update set family=excluded.family,label=excluded.label,sort_order=excluded.sort_order,active=true;

on conflict(code) do update set title=excluded.title,priority=excluded.priority,sort_order=excluded.sort_order,active=true,updated_at=now();

on conflict(code) do update set title=excluded.title,source_kind=excluded.source_kind,normative_authority=excluded.normative_authority,notes=excluded.notes,updated_at=now();

on conflict(ruleset_key,jurisdiction) do nothing;




